item.command:
/bin/bash -lc "python - <<'PY'
import requests
for repo in ['anndata','scanpy','python']:
 url=f'https://quay.io/api/v1/repository/biocontainers/{repo}/tag/?limit=20&onlyActiveTags=true'
 try:
  r=requests.get(url,timeout=10)
  if r.status_code==200:
   print(repo)
   for tag in r.json().get('tags',[])[:20]: print(' ', tag.get('name'))
 except Exception as e: print(repo,e)
PY"

